window.kbPageData["views/entry/k-118295d3a63ccf84"] = {"key":"entry/k-118295d3a63ccf84","state":{"route":"entry/k-118295d3a63ccf84"},"node":{"id":"k-118295d3a63ccf84","mode":"k","title":"经济思想","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["观点与论证"],"出处性质":["理论手册"],"学科":["政治理论"],"来源主题":["新时代中国特色社会主义思想"],"资料类别":["非时政"]},"directorySummary":"2022 年 6 月，由中共中央宣传部、国家发展和改革委员会组织编写的《习近平经济思\n想学习纲要》，将习近平经济思想基本内容梳理归纳为十三个方面：\n（1）加强党对经济工作的全面领导是我国经济发展的根本保证；\n（2）坚持以人民为中心的发展思想是我国经济发展的根本立场；\n（3）进入新发展阶段是我国经济发…","sources":[{"id":"f207988023f76a97","label":"经济思想","topic":"新时代中国特色社会主义思想","category":"非时政","text":"2022 年 6 月，由中共中央宣传部、国家发展和改革委员会组织编写的《习近平经济思\n想学习纲要》，将习近平经济思想基本内容梳理归纳为十三个方面：\n（1）加强党对经济工作的全面领导是我国经济发展的根本保证；\n（2）坚持以人民为中心的发展思想是我国经济发展的根本立场；\n（3）进入新发展阶段是我国经济发展的历史方位；\n（4）坚持新发展理念是我国经济发展的指导原则；\n◎粉笔拓展\n新发展理念包括：创新、协调、绿色、开放、共享。其中，创新是引领发展的第一动力。\n协调是持续健康发展的内在要求。绿色是永续发展的必要条件和人民对美好生活追求的重要\n体现。开放是国家繁荣发展的必由之路。共享是中国特色社会主义的本质要求。\n（5）构建新发展格局是我国经济发展的路径选择；\n（6）推动高质量发展是我国经济发展的鲜明主题；\n（7）坚持和完善社会主义基本经济制度是我国经济发展的制度基础；\n（8）坚持问题导向部署实施国家重大发展战略是我国经济发展的战略举措；\n（9）坚持创新驱动发展是我国经济发展的第一动力；\n（10）大力发展制造业和实体经济是我国经济发展的主要着力点；\n（11）坚定不移全面扩大开放是我国经济发展的重要法宝；\n（12）统筹发展和安全是我国经济发展的重要保障；\n（13）坚持正确工作策略和方法是做好经济工作的方法论。","source":{"doc":"3ccc56f4000d1642c2d1","first":19,"last":20,"page":19,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{},"terms":{},"references":{},"topics":[],"units":{"k-118295d3a63ccf84":[]}};
